src = p.read_text()

old = '''    import math

    thousands_sep = thousands_separator()
    decimal_sep = decimal_separator()
    try:
        if isinstance(value, str):
            value = value.replace(thousands_sep, "").replace(decimal_sep, ".")
            if not math.isfinite(float(value)):
                return _format_not_finite(float(value))
            if "." in value:
                value = float(value)
            else:
                value = int(value)
        else:
            if not math.isfinite(float(value)):
                return _format_not_finite(float(value))
            float(value)
    except (TypeError, ValueError):
        return str(value)

    if ndigits is not None:
        result = f"{value:,.{ndigits}f}"
    else:
        result = f"{value:,}"
    if thousands_sep != "," or decimal_sep != ".":
        result = result.translate(str.maketrans(",.", thousands_sep + decimal_sep))
    return result
'''

new = '''    import math

    thousands_sep = thousands_separator()
    decimal_sep = decimal_separator()
    try:
        if isinstance(value, str):
            value = value.replace(thousands_sep, "").replace(decimal_sep, ".")
            if "." in value:
                value = float(value)
            else:
                try:
                    # ``int()`` accepts arbitrarily large integer strings, which
                    # must not be routed through ``float()``.
                    value = int(value)
                except ValueError:
                    if not math.isfinite(float(value)):
                        return _format_not_finite(float(value))
                    return str(value)
        elif isinstance(value, float):
            if not math.isfinite(value):
                return _format_not_finite(value)
        else:
            try:
                if not math.isfinite(float(value)):
                    return _format_not_finite(float(value))
            except OverflowError:
                # A Python int beyond the floating point range is still finite.
                pass
    except (TypeError, ValueError):
        return str(value)

    try:
        if ndigits is not None:
            result = f"{value:,.{ndigits}f}"
        else:
            result = f"{value:,}"
    except OverflowError:
        # ``f`` formatting coerces ints to float, which overflows for very large
        # integers. Fall back to integer grouping plus the requested precision.
        result = f"{value:,}"
        if ndigits is not None:
            result += "." + "0" * ndigits
    if thousands_sep != "," or decimal_sep != ".":
        result = result.translate(str.maketrans(",.", thousands_sep + decimal_sep))
    return result
'''

assert old in src, "old block not found"
src = src.replace(old, new, 1)
p.write_text(src)
print("patched")
